PROGRAM P_corpus
VAR x : REAL; y : REAL; b : BOOL; n : INT; t : TIME; END_VAR
b := x > y;
b := x <= y;
b := x <> y;
END_PROGRAM

PROGRAM P_corpus
VAR x : REAL; y : REAL; b : BOOL; n : INT; t : TIME; END_VAR
IF b THEN
x := 1.0;
ELSIF y > 0.0 THEN
x := 2.0;
ELSE
x := 3.0;
END_IF;
END_PROGRAM

PROGRAM P_corpus
VAR x : REAL; y : REAL; b : BOOL; n : INT; t : TIME; END_VAR
CASE n OF
1: x := 1.0;
2: x := 2.0;
ELSE
x := 0.0;
END_CASE;
END_PROGRAM

PROGRAM P_corpus
VAR b : BOOL; TON_1 : TON; END_VAR
TON_1(IN := b, PT := T#5s);
b := TON_1.Q;
END_PROGRAM

PROGRAM P_corpus
VAR x : REAL; y : REAL; b : BOOL; n : INT; t : TIME; END_VAR
FOR n := 1 TO 3 DO
x := x + 1.0;
END_FOR;
END_PROGRAM

PROGRAM P_corpus
VAR x : REAL; y : REAL; b : BOOL; n : INT; t : TIME; END_VAR
WHILE b DO
x := x + 1.0;
END_WHILE;
END_PROGRAM
